# DK VNB.  Vollerup - Nordborg
#
let vn = path("d3.dk.vnb");

with detail = 3, railway = :first :g1000 :pax :removed {
    # point.dk.Vollerup-ABA dk.SSB

    with link = "line.dk.VNB" {
        track(vn[:vol.yn, :vol.yn + 1.31km]);
        line_label(:left:e, vn[:vol.yn + 1.3km] << 0.5lt, "VNB");
        track(vn[:vol.yn + 1.29km, :aug - 0.49sw]);
    }

    with link = "point.dk.Augustenborg", railway = :station {
        track(vn[:aug - 0.5sw, :aug + 0.5sw]);
        marker(:left :de.bf, vn[:aug] << 0.5lt);
        slabel(:left, vn[:aug] << 0.5lt << 1sh + (-1.2dt, 0.9dt),
            "Augustenborg"
        );
    }

    with link = "line.dk.VNB" {
        track(vn[:aug + 0.49sw, :bro - 0.49sw]);
    }

    with link = "point.dk.Bro", railway = :station {
        track(vn[:bro - 0.5sw, :bro + 0.5sw]);
        marker(:right :de.hp, vn[:bro] >> 0.5lt);
        slabel(:right, vn[:bro] >> 0.5lt >> 1sh + (1.4dt, 1.3dt),
            "Bro"
        );
    }

    with link = "line.dk.VNB" {
        track(vn[:bro + 0.49sw, :ket - 0.49sw]);
    }

    with link = "point.dk.Ketting", railway = :station {
        track(vn[:ket - 0.5sw, :ket + 0.5sw]);
        marker(:left :de.hp, vn[:ket] << 0.5lt);
        slabel(:left, vn[:ket] << 0.5lt << 1sh + (-1.5dt, 0.6dt),
            "Ketting"
        );
    }

    with link = "line.dk.VNB" {
        track(vn[:ket + 0.49sw, :ass - 0.49sw]);
    }

    with link = "point.dk.Asserballe", railway = :station {
        track(vn[:ass - 0.5sw, :ass + 0.5sw]);
        marker(:right :de.bf, vn[:ass] >> 0.5lt);
        slabel(:right, vn[:ass] >> 0.5lt >> 1sh + (1.3dt, 1.4dt),
            "Asserballe"
        );
    }

    with link = "line.dk.VNB" {
        track(vn[:ass + 0.49sw, :not - 0.49sw]);
    }

    with link = "point.dk.Notmark-Hundslev", railway = :station {
        track(vn[:not - 0.5sw, :not + 0.5sw]);
        marker(:left :de.bf, vn[:not] << 0.5lt);
        slabel(:right, vn[:not] >> 0.5lt + (1.5dt, 0.5dt),
