        slabel(:top, vn[:els] >> 0.5lt >> 1sh + (0.5dt, -0.3dt),
            "Elstrup"
        );
    }

    with link = "line.dk.VNB" {
        track(vn[:els + 0.49sw, :gud - 0.49sw]);
    }

    with link = "point.dk.Guderup", railway = :station {
        track(vn[:gud - 0.5sw, :gud + 0.5sw]);
        marker(:left :de.bf, vn[:gud] << 0.5lt);
        slabel(:left, vn[:gud] << 0.5lt << 1sh + (-1.5dt, 1.5dt),
