    }

    with link = "line.dk.VNB" {
        track(vn[:ste + 0.49sw, :sve - 0.49sw]);
    }

    with link = "point.dk.Svenstrup-Als", railway = :station {
        track(vn[:sve - 0.5sw, :sve + 0.5sw]);
        marker(:right :de.bf, vn[:sve] >> 0.5lt);
        slabel(:right, vn[:sve] >> 0.5lt >> 1sh + (1.6dt, 0.2dt),
            "Svenstrup"
        );
    }

    with link = "line.dk.VNB" {
        track(vn[:sve + 0.49sw, :hav - 0.49sw]);
