        );
    }

    with link = "line.dk.VNB" {
        track(vn[:hav + 0.49sw, :oks - 0.49sw]);
    }

    with link = "point.dk.Oksbøl-Als", railway = :station {
        track(vn[:oks - 0.5sw, :oks + 0.5sw]);
        marker(:left :de.bf, vn[:oks] << 0.5lt);
        slabel(:left, vn[:oks] << 0.5lt << 1sh + (-1.5dt, 1.3dt),
