    with link = "line.dk.VNB" {
        track(vn[:oks + 0.49sw, :oks + 0.91km]);
        line_label(:left:e, vn[:oks + 0.9km] << 0.5lt, "VNB");
        track(vn[:oks + 0.89km, :nor - 0.49sw]);
